import{_ as s,o as a,c as e,a7 as t}from"./chunks/framework.DUCm5Bu5.js";const c=JSON.parse('{"title":"快速入門","description":"從已建置的取出啟動隔離的本機伺服器，並確認它正在執行。","frontmatter":{"title":"快速入門","description":"從已建置的取出啟動隔離的本機伺服器，並確認它正在執行。","updated":"2026-10-18T00:00:00.000Z"},"headers":[],"relativePath":"zh-tw/getting-started/quickstart.md","filePath":"zh-tw/getting-started/quickstart.md"}'),l={name:"zh-tw/getting-started/quickstart.md"};function h(n,i,p,o,d,r){return a(),e("div",null,[...i[0]||(i[0]=[t('<p>本頁使用你在<a href="./installation">安裝</a>中建置好的取出，啟動一個使用記憶體持續性的本機隔離伺服器。它先以無遊戲監聽的管理 profile <code>management</code> 完成第一次成功檢查，然後說明 <code>kr-812</code> 這類遊戲 profile 有何不同，以及這些檢查能證明什麼、不能證明什麼。</p><p><strong>本頁適合：</strong> 已完成原始碼建置、希望在幾分鐘內跑起本機伺服器的讀者。</p><h2 id="你將得到什麼" tabindex="-1">你將得到什麼 <a class="header-anchor" href="#你將得到什麼" aria-label="Permalink to &quot;你將得到什麼&quot;">​</a></h2><p>一個可以安全啟動與停止的本機伺服器處理程序，使用記憶體持續性，不連接任何真實資料庫。處理程序結束後帳號與進度都會重置。它不是可完整遊玩的伺服器，也不能證明遊戲用戶端可用。</p><p><code>management</code> profile 只啟動管理 API 與 WebUI，沒有遊戲或中繼監聽，因此不需要用戶端資料即可執行。<code>kr-812</code> 這類遊戲 profile 還需要該版本對應的本機用戶端資料，而儲存庫不包含這些資料。</p><h2 id="開始之前" tabindex="-1">開始之前 <a class="header-anchor" href="#開始之前" aria-label="Permalink to &quot;開始之前&quot;">​</a></h2><ul><li>已完成<a href="./installation">安裝</a>：解決方案以零警告建置成功，且建置輸出存在。</li><li>終端機位於儲存庫根目錄；本頁所有命令都在此執行。</li><li>.NET 10 SDK 可用：<code>dotnet --version</code> 輸出 10.x 版本。</li><li>本機檢查修補檔存在。在 PowerShell 中用 <code>Test-Path tools/local-checks/isolated-memory.patch.yaml</code> 檢查，或在 POSIX shell 中用 <code>test -f tools/local-checks/isolated-memory.patch.yaml</code> 檢查。</li><li>下一步會建立 <code>.env</code> 檔案。</li><li>選用：如果本次要啟動 <code>kr-812</code>，相符的用戶端資料已在 <code>client-data/kr-812/data</code> 或 <code>client-data/kr-812/dataraw</code> 下。</li></ul><h2 id="準備本機環境變數檔案" tabindex="-1">準備本機環境變數檔案 <a class="header-anchor" href="#準備本機環境變數檔案" aria-label="Permalink to &quot;準備本機環境變數檔案&quot;">​</a></h2><p>profile 在組合時就會插入環境變數，此時任何修補檔都還沒有停用服務。因此即使是記憶體檢查，也必須存在本機的 MySQL 密碼變數。</p><h3 id="_1-複製範例檔案" tabindex="-1">1. 複製範例檔案 <a class="header-anchor" href="#_1-複製範例檔案" aria-label="Permalink to &quot;1. 複製範例檔案&quot;">​</a></h3><p>PowerShell：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Copy-Item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .env.example .env</span></span></code></pre></div><p>Linux shell：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p><code>.env</code> 被 Git 忽略，絕不要提交。</p><h3 id="_2-設定臨時密碼" tabindex="-1">2. 設定臨時密碼 <a class="header-anchor" href="#_2-設定臨時密碼" aria-label="Permalink to &quot;2. 設定臨時密碼&quot;">​</a></h3><p>開啟 <code>.env</code>，把 <code>BFF_MYSQL_PASSWORD</code> 設為非空的臨時值，例如 <code>isolated-check-only</code>。<code>persistence.mysql</code> 列讀取沒有預設值的 <code>${BFF_MYSQL_PASSWORD}</code>，變數缺少時組合會失敗；隔離記憶體修補檔只在組合之後才停用該列。本機檢查不要使用真實資料庫憑證，真實憑證只用於刻意設定的部署。</p><p><strong>檢查是否成功：</strong> <code>.env</code> 存在（<code>Test-Path .env</code> 輸出 <code>True</code>），且 <code>BFF_MYSQL_PASSWORD</code> 列非空。不要把該檔案或其值貼到聊天或問題中。</p><h2 id="找到-profile" tabindex="-1">找到 profile <a class="header-anchor" href="#找到-profile" aria-label="Permalink to &quot;找到 profile&quot;">​</a></h2><p>profile 指定一個用戶端版本，並組合該版本使用的模組列。它的 id 是 <code>&lt;region&gt;-&lt;wire version&gt;</code>，其中數字是用戶端的 <code>ClientVersion_Major</code>，不是執行檔的檔案版本。<code>management</code> 是僅管理用途的 profile；<code>setup</code> 是首次執行助理。</p><h3 id="_1-列出隨附的-profile" tabindex="-1">1. 列出隨附的 profile <a class="header-anchor" href="#_1-列出隨附的-profile" aria-label="Permalink to &quot;1. 列出隨附的 profile&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BubbleFighter.Fantasy.Host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> profiles list</span></span></code></pre></div><p>命令為每個 profile 輸出一行：id 與描述。本版本列出 19 個。其中兩行比較有用：<code>management</code>（“Administration and durable storage only; no game or relay ports.”）與 <code>kr-812</code>（“Korean 2015 client build, ClientVersion_Major 812, resource patch 458.”）。</p><p>列出某個 profile 不代表該版本的全部玩法都已實作；不同 profile 可用的功能與所需資料不同。</p><h3 id="_2-列出找到的模組" tabindex="-1">2. 列出找到的模組 <a class="header-anchor" href="#_2-列出找到的模組" aria-label="Permalink to &quot;2. 列出找到的模組&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BubbleFighter.Fantasy.Host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> plugins list</span></span></code></pre></div><p>命令為每個模組定義輸出一行：模組 id、版本、支援的用戶端版本以及載入來源。這就是 Host 可以掛載到 profile 中的實作集合。</p><p><strong>檢查是否成功：</strong> 兩條命令都成功結束並輸出內容，沒有 profile 或模組掃描錯誤。</p><h2 id="檢查生效的設定" tabindex="-1">檢查生效的設定 <a class="header-anchor" href="#檢查生效的設定" aria-label="Permalink to &quot;檢查生效的設定&quot;">​</a></h2><p>用本機檢查修補檔組合 <code>kr-812</code>，在不啟動任何東西的情況下列印結果：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BubbleFighter.Fantasy.Host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">profile kr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">812</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patch tools</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">local</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">checks</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">isolated</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">memory.patch.yaml </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dump</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config</span></span></code></pre></div><p>命令以 YAML 輸出生效的列清單，並以結束碼 0 結束。請在輸出中尋找以下列：</p><ul><li><code>id: persistence.mysql</code> 後面跟著 <code>disabled: true</code>；</li><li><code>id: persistence.memory</code> 沒有 <code>disabled: true</code>，即已啟用；</li><li><code>id: clientdata</code> 顯示 <code>kr-812</code> 解析後的 <code>data_directory</code> 與 <code>raw_directory</code>。</li></ul><p>隔離修補檔最後套用，因此會覆寫開發者 <code>.env</code> 或 <code>local.patch.yaml</code> 中把 MySQL 指向真實資料庫的設定。匯出會在任何模組啟用之前結束，因此只能證明組合與驗證，不能證明 profile 能啟動。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>當修補檔啟用 MySQL 時，匯出可能包含插值後的值，包括憑證。請把它視為敏感內容。</p></div><h2 id="啟動伺服器" tabindex="-1">啟動伺服器 <a class="header-anchor" href="#啟動伺服器" aria-label="Permalink to &quot;啟動伺服器&quot;">​</a></h2><h3 id="_1-啟動無遊戲的本機伺服器" tabindex="-1">1. 啟動無遊戲的本機伺服器 <a class="header-anchor" href="#_1-啟動無遊戲的本機伺服器" aria-label="Permalink to &quot;1. 啟動無遊戲的本機伺服器&quot;">​</a></h3><p>在儲存庫根目錄執行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BubbleFighter.Fantasy.Host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">profile management </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patch tools</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">local</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">checks</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">isolated</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">memory.patch.yaml</span></span></code></pre></div><p>如果儲存庫根目錄存在 <code>.env</code>，第一行是 <code>Loaded unset variables from &lt;path&gt;.</code>。隨後伺服器會列印管理監聽位址、WebUI 位址與作用中的列數：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Row &#39;admin.http&#39; admin API listening on 127.0.0.1:8080.</span></span>\n<span class="line"><span>WebUI: http://127.0.0.1:8080/</span></span>\n<span class="line"><span>Server started with &lt;count&gt; active row(s).</span></span></code></pre></div><p><code>&lt;count&gt;</code> 是 Host 列印的作用中列數量，不是固定數字。<code>management</code> 沒有遊戲或中繼連接埠。它的管理 API 基礎位址是 <code>http://127.0.0.1:8080</code>，來自 <code>profiles/bundles/core.yaml</code> 中的 <code>admin.http</code> 列（<code>${BFF_ADMIN_HOST:-127.0.0.1}:${BFF_ADMIN_PORT:-8080}</code>）。處理程序會一直保持在前景，直到你停止它。</p><h3 id="_2-改為啟動遊戲-profile-需要用戶端資料" tabindex="-1">2. 改為啟動遊戲 profile（需要用戶端資料） <a class="header-anchor" href="#_2-改為啟動遊戲-profile-需要用戶端資料" aria-label="Permalink to &quot;2. 改為啟動遊戲 profile（需要用戶端資料）&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BubbleFighter.Fantasy.Host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">profile kr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">812</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patch tools</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">local</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">checks</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">isolated</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">memory.patch.yaml</span></span></code></pre></div><p>遊戲 profile 需要相符的用戶端資料。缺少資料時，<code>clientdata</code> 列會失敗，啟動會以下列訊息停止：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>clientdata: neither data_directory &#39;&lt;working-directory&gt;/client-data/kr-812/data&#39; nor raw_directory &#39;&lt;working-directory&gt;/client-data/kr-812/dataraw&#39; exists. Provision the configured client-data directories before enabling this row.</span></span></code></pre></div><p>請提供資料，或依<a href="./installation">安裝</a>所述透過安裝助理匯入，然後重新啟動該 profile。資料就位後，<code>kr-812</code> 會在 <code>${BFF_BIND_HOST:-0.0.0.0}:${LEGACY_PORT}</code> 上綁定遊戲監聽，因為 <code>profiles/kr-812/profile.yaml</code> 把 <code>LEGACY_PORT</code> 設為 <code>${KR_812_GAME_PORT:-7110}</code>，所以實際是 <code>0.0.0.0:7110</code>。舊版（legacy）版本沒有中繼監聽。管理 API 仍是 <code>127.0.0.1:8080</code>。</p><p><strong>檢查是否成功：</strong> 處理程序保持在前景，列印上面三行啟動資訊，且沒有以啟用錯誤結束。</p><h2 id="確認它正在執行" tabindex="-1">確認它正在執行 <a class="header-anchor" href="#確認它正在執行" aria-label="Permalink to &quot;確認它正在執行&quot;">​</a></h2><h3 id="_1-檢查健康檢查端點" tabindex="-1">1. 檢查健康檢查端點 <a class="header-anchor" href="#_1-檢查健康檢查端點" aria-label="Permalink to &quot;1. 檢查健康檢查端點&quot;">​</a></h3><p>PowerShell：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-RestMethod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> http:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">127.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8080</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">health</span></span></code></pre></div><p>Linux shell：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/health</span></span></code></pre></div><p>回應包含 <code>status</code> = <code>ok</code> 以及 UTC 時間戳。即使設定了 admin token，<code>/health</code> 也始終開放。</p><h3 id="_2-檢查執行階段實例" tabindex="-1">2. 檢查執行階段實例 <a class="header-anchor" href="#_2-檢查執行階段實例" aria-label="Permalink to &quot;2. 檢查執行階段實例&quot;">​</a></h3><p>PowerShell：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-RestMethod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> http:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">127.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8080</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">plugins </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Format-Table</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rowId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> state</span></span></code></pre></div><p>Linux shell：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/api/plugins</span></span></code></pre></div><p><code>/api/plugins</code> 傳回正在執行的模組列。每一項包含 <code>rowId</code>、<code>plugin</code>、<code>source</code>、<code>state</code> 與 <code>error</code>。請尋找 <code>state</code> = <code>Active</code> 且 <code>error</code> 為空的列；<code>Failed</code> 或 <code>Pending</code> 列會在 <code>error</code> 中提供診斷資訊。</p><p>如果在 <code>.env</code> 中設定了 <code>BFF_ADMIN_TOKEN</code>，每個 <code>/api</code> 呼叫都需要 bearer token：給 <code>Invoke-RestMethod</code> 加上 <code>-Headers @{ Authorization = &quot;Bearer &lt;token&gt;&quot; }</code>，或給 <code>curl</code> 加上 <code>-H &quot;Authorization: Bearer &lt;token&gt;&quot;</code>。WebUI 檔案與 <code>/health</code> 始終開放，以便瀏覽器載入登入頁。</p><h3 id="_3-開啟-webui" tabindex="-1">3. 開啟 WebUI <a class="header-anchor" href="#_3-開啟-webui" aria-label="Permalink to &quot;3. 開啟 WebUI&quot;">​</a></h3><p>在瀏覽器開啟 <code>http://127.0.0.1:8080/</code>。management profile 會提供管理介面。</p><p><strong>檢查是否成功：</strong> 健康檢查傳回 <code>ok</code>，實例清單顯示作用中的列，且 WebUI 可以載入。這些檢查證明 Host 及其管理 API 正在執行；它們不能證明遊戲用戶端可以連線。</p><h2 id="停止伺服器" tabindex="-1">停止伺服器 <a class="header-anchor" href="#停止伺服器" aria-label="Permalink to &quot;停止伺服器&quot;">​</a></h2><p>在執行伺服器的終端機按 Ctrl+C。主控台會列印 <code>Shutdown complete.</code>，隨後處理程序結束。記憶體中的帳號與進度隨處理程序一起捨棄；對本機檢查來說停止總是安全的，因為沒有任何持續性資料被更動。</p><p>如果希望資料在重新啟動後保留，請依<a href="./../guides/configuration">伺服器設定</a>把持續性切換到 SQLite 或 MySQL。隔離記憶體修補檔只用於本機檢查。</p><h2 id="這不能證明什麼" tabindex="-1">這不能證明什麼 <a class="header-anchor" href="#這不能證明什麼" aria-label="Permalink to &quot;這不能證明什麼&quot;">​</a></h2><ul><li>沒有遊戲用戶端登入，也沒有驗證任何玩法或封包相容性。</li><li>management profile 沒有遊戲或中繼監聽，因此完全沒有用戶端流量。</li><li>設定檢查或自動檢查通過不等於真實用戶端驗收；請另行用真實用戶端驗證目標登入與遊戲流程。</li></ul><h2 id="發生問題時" tabindex="-1">發生問題時 <a class="header-anchor" href="#發生問題時" aria-label="Permalink to &quot;發生問題時&quot;">​</a></h2><ul><li><strong><code>environment variable &#39;BFF_MYSQL_PASSWORD&#39; is not set and has no default</code>：</strong> <code>.env</code> 檔案缺少、沒有在儲存庫根目錄找到，或沒有設定該變數。請複製 <code>.env.example</code> 並設定一個臨時值。</li><li><strong>管理連接埠已被占用：</strong> 啟動會在監聽列失敗。請在 <code>.env</code> 中設定 <code>BFF_ADMIN_PORT</code>，或停止占用 8080 的處理程序。</li><li><strong>遊戲連接埠已被占用：</strong> 請在 <code>.env</code> 中設定 <code>KR_812_GAME_PORT</code>，或停止占用 7110 的處理程序。</li><li><strong><code>kr-812</code> 因 <code>clientdata</code> 失敗：</strong> 參見上面的用戶端資料訊息；該版本的資料必須存在，profile 才能啟動。</li><li><strong><code>Server startup did not converge</code>：</strong> 訊息會列出每個未啟用的列及其狀態與診斷。先閱讀第一個 <code>Failed</code> 或 <code>Pending</code> 列並修正其原因。</li></ul><p>更多情況見<a href="./../guides/troubleshooting">疑難排解</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>繼續閱讀<a href="./../guides/configuration">伺服器設定</a>，了解持續性、連接埠、profile 與環境變數；然後閱讀<a href="./../guides/plugins">模組</a>，了解模組列的運作方式以及如何掛載自己的模組。配套啟動器如何安裝用戶端並連線伺服器，見<a href="./../guides/launcher">啟動器</a>。</p>',75)])])}const g=s(l,[["render",h]]);export{c as __pageData,g as default};
